/**
 * The nine official GHS hazard pictograms (UNECE artwork, public domain): the very SVG files of the plugin's
 * Resources/Ghs, which flutter-chemistry pins in tool/fetch_ghs_pictograms.sh, base64-encoded. Inlined because CI and
 * the host build copy only this Angular module, so a separate asset file would not be served; nothing is fetched at
 * runtime. ChemicalGhsPictogramsTests (C#) fails when a string here drifts from its SVG file.
 */
export const GHS_PICTOGRAM_BASE64: Readonly<Record<string, string>> = {
  // SHA-1 49deeaed978e3dea8a4f74b4309a5c4a7671cad8
  GHS01: '',
  // SHA-1 47a26281017faf09f2c0c05ac03d9711ec32ffc6
  GHS02: '',
  // SHA-1 a09ecfa77ba52b79ca037f99e316963ed46c4eeb
  GHS03: '',
  // SHA-1 5bb4e2ce36a676db86ab4e9552b9fe0b35de14bd
  GHS04: '',
  // SHA-1 8bcb729fdedca2dceb74631cd7cd059315bf91cf
  GHS05: '',
  // SHA-1 c1eac17decdf00e8b7515b57fe5006cb9be6b8d7
  GHS06: '',
  // SHA-1 a6e245132c742b95295e7194e79a5299b7de91b2
  GHS07: '',
  // SHA-1 12a0d5263a9dec1ee9f256fbabd7fba46725ad49
  GHS08: '',
  // SHA-1 f38551d20f5c72ac5a8e9eb708f92b647c60905a
  GHS09: '',
};

/** A data: URL of the pictogram's SVG, or null for a code without official artwork (it stays a text chip). */
export function ghsPictogramSrc(code: string | null | undefined): string | null {
  const base64 = GHS_PICTOGRAM_BASE64[(code ?? '').trim().toUpperCase()];
  return base64 ? `data:image/svg+xml;base64,${base64}` : null;
}
